function MillstoneDressingHammerMaker.init() MillstoneDressingHammerMaker.ironStock=18; MillstoneDressingHammerMaker.bronzeStock=14; MillstoneDressingHammerMaker.woodStock=10; MillstoneDressingHammerMaker.leatherStock=8; MillstoneDressingHammerMaker.silverStock=8; MillstoneDressingHammerMaker.goldStock=6; MillstoneDressingHammerMaker.jewelStock=4; MillstoneDressingHammerMaker.pearlStock=4; MillstoneDressingHammerMaker.productStock={}; MillstoneDressingHammerMaker.buildings={}; MillstoneDressingHammerMaker.maker=nil; MillstoneDressingHammerMaker.activeMaking={}; MillstoneDressingHammerMaker.totalProducts=0; MillstoneDressingHammerMaker.dayTimer=0; print("[MillstoneDressingHammerMaker] Royal Millstone Dressing Hammer Maker System initialized (6 products, 4 buildings)") end
function MillstoneDressingHammerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneDressingHammerMaker.maker={name=n or ("Kladivar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kladivar najet: %s (spretnost: %d)",MillstoneDressingHammerMaker.maker.name,s),"success") end; return true end
function MillstoneDressingHammerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneDressingHammerMaker.build(id) local ok,e=MillstoneDressingHammerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneDressingHammerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneDressingHammerMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneDressingHammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneDressingHammerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneDressingHammerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneDressingHammerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneDressingHammerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneDressingHammerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneDressingHammerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneDressingHammerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneDressingHammerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneDressingHammerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneDressingHammerMaker.buildings==0 then return false,"Potrebna kladivna delavnica" end; if not MillstoneDressingHammerMaker.maker then return false,"Potreben kladivar" end; return true end
function MillstoneDressingHammerMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneDressingHammerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneDressingHammerMaker.ironStock=MillstoneDressingHammerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneDressingHammerMaker.bronzeStock=MillstoneDressingHammerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneDressingHammerMaker.woodStock=MillstoneDressingHammerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneDressingHammerMaker.leatherStock=MillstoneDressingHammerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneDressingHammerMaker.silverStock=MillstoneDressingHammerMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneDressingHammerMaker.goldStock=MillstoneDressingHammerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneDressingHammerMaker.jewelStock=MillstoneDressingHammerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneDressingHammerMaker.pearlStock=MillstoneDressingHammerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneDressingHammerMaker.maker then t=math.max(1,t-math.floor(MillstoneDressingHammerMaker.maker.skill/13)) end; table.insert(MillstoneDressingHammerMaker.activeMaking,{id="millstonedressinghammer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneDressingHammerMaker.completeMaking(m) local q=1.0+(MillstoneDressingHammerMaker.getQualityBonus()/100); if MillstoneDressingHammerMaker.maker then q=q+(MillstoneDressingHammerMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneDressingHammerMaker.productStock[m.productType]=(MillstoneDressingHammerMaker.productStock[m.productType] or 0)+m.quantity; MillstoneDressingHammerMaker.totalProducts=MillstoneDressingHammerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneDressingHammerMaker.maker then MillstoneDressingHammerMaker.maker.itemsMade=MillstoneDressingHammerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneDressingHammerMaker.maker.skill=math.min(100,MillstoneDressingHammerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kladivo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonedressinghammer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneDressingHammerMaker.update(dt) if not _G.state then return end; MillstoneDressingHammerMaker.dayTimer=MillstoneDressingHammerMaker.dayTimer+dt; if MillstoneDressingHammerMaker.dayTimer>=30 then MillstoneDressingHammerMaker.dayTimer=0; for i=#MillstoneDressingHammerMaker.activeMaking,1,-1 do local m=MillstoneDressingHammerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneDressingHammerMaker.completeMaking(m); table.remove(MillstoneDressingHammerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneDressingHammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneDressingHammerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneDressingHammerMaker.getStats() return {ironStock=MillstoneDressingHammerMaker.ironStock,bronzeStock=MillstoneDressingHammerMaker.bronzeStock,woodStock=MillstoneDressingHammerMaker.woodStock,leatherStock=MillstoneDressingHammerMaker.leatherStock,silverStock=MillstoneDressingHammerMaker.silverStock,goldStock=MillstoneDressingHammerMaker.goldStock,jewelStock=MillstoneDressingHammerMaker.jewelStock,pearlStock=MillstoneDressingHammerMaker.pearlStock,productStock=MillstoneDressingHammerMaker.productStock,numBuildings=#MillstoneDressingHammerMaker.buildings,hasMaker=MillstoneDressingHammerMaker.maker~=nil,makerName=MillstoneDressingHammerMaker.maker and MillstoneDressingHammerMaker.maker.name or "—",makerSkill=MillstoneDressingHammerMaker.maker and MillstoneDressingHammerMaker.maker.skill or 0,activeMaking=#MillstoneDressingHammerMaker.activeMaking,totalProducts=MillstoneDressingHammerMaker.totalProducts} end
